    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "To improve older patients' physical activity (PA) behavior, it is important to identify facilitators and barriers to enhancing PA in older patients ( ≥ 65 years) during hospitalization from the perspectives of patients, caregivers, and healthcare professionals (HCPs).",
      "reason": "The abstract background states the importance of identifying facilitators and barriers, partially conveying the need for the review, but a fuller rationale in the Introduction is not evidenced."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved evidence identifies or cites previous similar systematic reviews or explains the need for the current review relative to them; the conditional requirement cannot be confirmed as addressed or as not applicable."
