    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of facilitators and barriers to physical activity, not a review of intervention effects, so describing a proposed mechanism of action of an intervention does not apply."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review identifies facilitators and barriers rather than evaluating a complex intervention, so a logic model of intervention components and outcomes is not required; the social ecological model is used as a categorization framework, not an intervention logic model."
    }
  ],
  "confidence": 70
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "To improve older patients' physical activity (PA) behavior, it is important to identify facilitators and barriers to enhancing PA in older patients ( ≥ 65 years) during hospitalization from the perspectives of patients, caregivers, and healthcare professionals (HCPs).",
      "reason": "The abstract's Background clearly states the review objective (identify facilitators and barriers to PA in hospitalized older patients from multiple perspectives), but it is not formulated using an explicit question-formulation framework (e.g., PICO, SPIDER, PICo), and no formal research question statement is present in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of facilitators and barriers (synthesis of qualitative, quantitative, and mixed-methods studies using the social ecological model), not a review of intervention effects, so planned comparisons in PICO form do not apply."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Studies were included if: 1) they were published between January 1, 2000, and May 29, 2021; 2) they were written in English, German, or Dutch; 3) they used a quantitative, qualitative, or mixed-methods study design; and 4) the study population consisted of patients aged ≥ 65 years (baseline mean age of 65 years or older), caregivers, or HCPs.",
      "reason": "Eligible designs, setting (hospitalization), population (≥65, caregivers, HCPs), and topic (facilitators/barriers to PA) are fully specified, along with exclusion criteria."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "1) they were published between January 1, 2000, and May 29, 2021; 2) they were written in English, German, or Dutch; ... Studies were excluded if they were: 1) editorials, opinion papers, conference abstracts, or literature reviews",
      "reason": "Dissemination date range, language restrictions, and publication status (excluded publication types) are all reported."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_11",
      "quote": "Full-text articles excluded, with reasons (n = 52): 16 based on other outcomes",
      "reason": "The flowchart (figure_3, text_11) reports exclusion 'based on other outcomes' but the review does not distinguish studies excluded because outcomes were not measured from those where outcomes were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "The adapted framework of the social ecological model [39] was therefore used, consisting of intrapersonal, interpersonal, and institutional levels (Additional file 4)",
      "reason": "Synthesis groupings are described (social ecological model levels, qualitative/quantitative/mixed-methods, best evidence synthesis quality categories in text_9), but explicit linkage of these groups to comparisons defined in the review objectives is not fully articulated."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "Given the specific hospital setting in the current review, in which patients enter a different and unfamiliar context, it is conceivable that facilitators and barriers might be different for patients over 65 years than for younger patients.",
      "reason": "A rationale is provided for the age restriction (≥65 years), but no rationale is given for other notable restrictions such as excluding patients with moderate to severe dementia or palliative patients."
    }
  ],
  "confidence": 88
}

